class Stack {
    private:
        int top;
        int capacity;
        int* arr;

    public:
        Stack(int n) : top(-1), capacity(n), arr(new int[n]) {}

        ~Stack() { delete[] arr; }

        void push(int x) {
            if (top == capacity - 1)
                throw "Overflow";
            arr[++top] = x;
        }

        int pop() {
            if (top == -1)
                throw "Underflow";
            return arr[top--];
        }
};

