def max_path_sum(test_array):
    n = len(test_array)
    m = len(test_array[0])

    # Initialize the dp table with zeros
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Fill the first row of the dp table
    for j in range(m):
        dp[0][j] = test_array[0][j]

    # Fill the rest of the dp table
    for i in range(1,n):
        for j in range(m):
            if j == 0:
                dp[i][j] = max(dp[i-1][j],dp[i-1][j+1]) + test_array[i][j]
            elif j == m - 1:
                dp[i][j] = max(dp[i-1][j],dp[i-1][j-1]) + test_array[i][j]
            else:
                dp[i][j] = max(dp[i-1][j],max(dp[i-1][j-1],dp[i-1][j+1])) + test_array[i][j]

    return max(dp[n-1])

